-- ref_outbox (control; single, cluster)
CREATE TABLE "orbit"."ref_outbox" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "dedupe_key" text COLLATE "C" NOT NULL CHECK (char_length("dedupe_key") <= 128),
  "channel" text COLLATE "C" NOT NULL CHECK (char_length("channel") <= 64),
  "state" text COLLATE "C" NOT NULL DEFAULT 'pending' CHECK (char_length("state") <= 16),
  "attempts" bigint NOT NULL DEFAULT 0,
  "next_at" bigint NOT NULL,
  "payload" jsonb NOT NULL,
  "secret" bytea,
  "weight" double precision,
  "enabled" boolean NOT NULL DEFAULT TRUE,
  "rule" text COLLATE "C" CHECK (char_length("rule") <= 64),
  CONSTRAINT "ref_outbox_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "ref_outbox_dedupe_key_key" ON "orbit"."ref_outbox" ("dedupe_key");
CREATE INDEX "ref_outbox_due" ON "orbit"."ref_outbox" ("state", "next_at" DESC) WHERE "state" = 'pending';
CREATE INDEX "ref_outbox_channel_idx" ON "orbit"."ref_outbox" ("channel") WHERE "weight" IS NOT NULL AND "enabled" = TRUE;

-- ref_rollup (series; single)
CREATE TABLE "orbit"."ref_rollup" (
  "series_id" bigint NOT NULL,
  "bucket" bigint NOT NULL,
  "min" double precision NOT NULL,
  "max" double precision NOT NULL,
  "sum" double precision NOT NULL,
  "count" bigint NOT NULL,
  "last" double precision,
  CONSTRAINT "ref_rollup_pkey" PRIMARY KEY ("series_id", "bucket")
);

-- ref_names (state; single, cluster)
CREATE TABLE "orbit"."ref_names" (
  "key" text COLLATE "C" NOT NULL CHECK (char_length("key") <= 225),
  "user" text CHECK (char_length("user") <= 64),
  "note" text NOT NULL,
  CONSTRAINT "ref_names_pkey" PRIMARY KEY ("key")
);

-- ref_head (series; cluster)
CREATE TABLE "orbit"."ref_head" (
  "shard" bigint NOT NULL,
  "target_id" bigint NOT NULL,
  "slot" bigint NOT NULL,
  "status" bigint NOT NULL,
  "vals" bytea NOT NULL,
  CONSTRAINT "ref_head_pkey" PRIMARY KEY ("shard", "target_id", "slot")
) PARTITION BY RANGE ("slot") /* hour partitions: the partition manager */;
